pub type Sentence = { words: Vec[Str]; }

impl IntoIterator for Sentence {
  type Item = Str;
  type IntoIter = VecIter[Str];

  fn into_iter(self: Sentence) -> VecIter[Str] {
    return self.words.into_iter();
  }
}

fn main() -> Int {
  let mut s = Sentence{ words: Vec[Str]() };
  s.words.push("Hello");
  s.words.push("World");
  s.words.push("from");
  s.words.push("XIOM");
  var count = 0;
  for word in s {
    count = count + 1;
  }
  return count;
}
